(7, 1, 2, CASE WHEN EXTRACT(ISO_DAY_OF_WEEK FROM DATEADD(DAY, -5, CURRENT_DATE)) = 7 THEN DATEADD(DAY, 1, DATEADD(DAY, -5, CURRENT_DATE)) ELSE DATEADD(DAY, -5, CURRENT_DATE) END, 'Control: mejora del dolor lumbar. Agregar masoterapia.'),
